CREATE TABLE alert_target_destinations(id TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES projects(id),label TEXT NOT NULL,target_type TEXT NOT NULL CHECK(target_type IN ('team','member','issue_owners')),target TEXT,fallthrough TEXT NOT NULL CHECK(fallthrough IN ('active_members','no_one')),created INTEGER NOT NULL);
CREATE INDEX alert_target_destinations_project ON alert_target_destinations(project);
CREATE TRIGGER alert_targets_capacity BEFORE INSERT ON alert_target_destinations WHEN (SELECT COUNT(*) FROM alert_target_destinations WHERE project=NEW.project)>=20 BEGIN SELECT RAISE(ABORT,'alert_destination_budget'); END;
-- A row (including an empty resolution) is immutable custody for one real intent.
CREATE TABLE alert_intent_recipients(intent TEXT PRIMARY KEY REFERENCES alert_intents(id),project TEXT NOT NULL REFERENCES projects(id),recipients TEXT NOT NULL CHECK(json_valid(recipients)),resolved INTEGER NOT NULL);
CREATE TRIGGER portability_alert_target_destinations_insert BEFORE INSERT ON alert_target_destinations WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_alert_target_destinations_update BEFORE UPDATE ON alert_target_destinations WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_alert_target_destinations_delete BEFORE DELETE ON alert_target_destinations WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER spool_owner_erasure_alert_target_destinations_insert BEFORE INSERT ON alert_target_destinations WHEN EXISTS(SELECT 1 FROM rer_erasure_operations WHERE entity='installation-owner' AND phase<>'complete') AND NOT EXISTS(SELECT 1 FROM rer_erasure_guard) BEGIN SELECT RAISE(ABORT,'owner_erasure_in_progress'); END;
CREATE TRIGGER spool_owner_erasure_alert_target_destinations_update BEFORE UPDATE ON alert_target_destinations WHEN EXISTS(SELECT 1 FROM rer_erasure_operations WHERE entity='installation-owner' AND phase<>'complete') AND NOT EXISTS(SELECT 1 FROM rer_erasure_guard) BEGIN SELECT RAISE(ABORT,'owner_erasure_in_progress'); END;
CREATE TRIGGER portability_alert_intent_recipients_insert BEFORE INSERT ON alert_intent_recipients WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_alert_intent_recipients_update BEFORE UPDATE ON alert_intent_recipients WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_alert_intent_recipients_delete BEFORE DELETE ON alert_intent_recipients WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER spool_owner_erasure_alert_intent_recipients_insert BEFORE INSERT ON alert_intent_recipients WHEN EXISTS(SELECT 1 FROM rer_erasure_operations WHERE entity='installation-owner' AND phase<>'complete') AND NOT EXISTS(SELECT 1 FROM rer_erasure_guard) BEGIN SELECT RAISE(ABORT,'owner_erasure_in_progress'); END;
CREATE TRIGGER spool_owner_erasure_alert_intent_recipients_update BEFORE UPDATE ON alert_intent_recipients WHEN EXISTS(SELECT 1 FROM rer_erasure_operations WHERE entity='installation-owner' AND phase<>'complete') AND NOT EXISTS(SELECT 1 FROM rer_erasure_guard) BEGIN SELECT RAISE(ABORT,'owner_erasure_in_progress'); END;
